gsap:
// anticipation: recua, depois dispara
tl.fromTo(el, { x: 0 }, { x: -50, duration: 0.15, ease: "power2.inOut" }, t);
tl.to(el, { x: 600, duration: 0.45, ease: "power3.out" }, t + 0.15);

// follow-through: corpo para; partes chegam depois e passam do ponto
tl.fromTo(el, { x: -500 }, { x: 0, duration: 0.5, ease: "power3.out" }, t);
tl.fromTo(items, { x: -500 }, { x: 0, duration: 0.6, ease: "back.out(2)", stagger: 0.06 }, t + 0.06);

// squash & stretch: bola caindo no chão (transformOrigin na base)
tl.fromTo(el, { y: -500, scaleX: 0.85, scaleY: 1.2 }, { y: 0, duration: 0.45, ease: "power2.in", transformOrigin: "50% 100%" }, t);
tl.to(el, { scaleX: 1.3, scaleY: 0.7, duration: 0.08, ease: "power2.out" }, t + 0.45);
tl.to(el, { scaleX: 1, scaleY: 1, duration: 0.5, ease: "elastic.out(1, 0.4)" }, t + 0.53);

// drag: el = corpo; a = parte solta (bandeira, cauda), origem no ponto de fixação
tl.fromTo(el, { x: 0 }, { x: 500, duration: 0.8, ease: "power2.inOut" }, t);
tl.fromTo(a, { x: 0 }, { x: 500, duration: 0.8, ease: "power2.inOut" }, t + 0.08);
tl.fromTo(a, { skewX: 0, transformOrigin: "0% 50%" }, { keyframes: { skewX: [0, -15, -10, 6, 0], easeEach: "sine.inOut" }, duration: 1.0, ease: "none" }, t);

// exaggeration: pico grande e assenta
tl.fromTo(el, { scale: 1, rotation: 0 }, { scale: 1.5, rotation: -15, duration: 0.18, ease: "power4.out" }, t);
tl.to(el, { scale: 1, rotation: 0, duration: 0.5, ease: "back.out(3)" }, t + 0.18);

// hit stop: chega, congela 0.1s tremendo de leve, depois rebate
const stop = 0.1;
tl.fromTo(el, { x: -600 }, { x: 0, duration: 0.25, ease: "power3.in" }, t);
tl.fromTo(el, { x: 0 }, { keyframes: { x: [0, 4, -4, 3, 0] }, duration: stop, ease: "none", immediateRender: false }, t + 0.25);
tl.to(el, { x: -40, duration: 0.3, ease: "power2.out" }, t + 0.25 + stop);

// impact frame: 2 quadros a 30 fps
const f = 1 / 30;
tl.set(scene, { filter: "invert(1) contrast(1.6)" }, t);
tl.set(scene, { filter: "none" }, t + 2 * f);

// inertia: chega rápido, inclina para a frente, endireita
tl.fromTo(el, { x: -700, skewX: 0, transformOrigin: "50% 100%" }, { x: 0, duration: 0.45, ease: "power4.out" }, t);
tl.fromTo(el, { skewX: 0 }, { keyframes: { skewX: [0, -8, 3, 0], easeEach: "sine.inOut" }, duration: 0.5, ease: "none", immediateRender: false }, t + 0.35);

// mass/peso: cai devagar no começo, bate seco, afunda e acomoda
tl.fromTo(el, { y: -600, scaleY: 1, transformOrigin: "50% 100%" }, { y: 0, duration: 0.7, ease: "power3.in" }, t);
tl.to(el, { scaleY: 0.92, y: 6, duration: 0.08, ease: "power2.out" }, t + 0.7);
tl.to(el, { scaleY: 1, y: 0, duration: 0.22, ease: "power2.out" }, t + 0.78);

// overlapping action: todos começam juntos, cada camada com tempo próprio
const layers = [[0.4, "power3.out"], [0.55, "power2.out"], [0.7, "back.out(1.4)"]];
items.forEach((it, i) => {
  const [d, e] = layers[i % layers.length];
  tl.fromTo(it, { y: 0 }, { y: -300, duration: d, ease: e }, t);
});

// recoil: ida seca, volta macia
tl.fromTo(el, { x: 0, rotation: 0 }, { x: -30, rotation: -4, duration: 0.06, ease: "power4.out" }, t);
tl.to(el, { x: 0, rotation: 0, duration: 0.4, ease: "power2.out" }, t + 0.06);

// secondary action: el = ação principal; a = detalhe que reage
tl.fromTo(el, { scale: 1 }, { scale: 0.9, duration: 0.12, ease: "power2.in", yoyo: true, repeat: 1 }, t);
tl.fromTo(a, { rotation: 0, scale: 1 }, { rotation: 20, scale: 1.1, duration: 0.25, ease: "power2.out", yoyo: true, repeat: 1 }, t + 0.1);

// staging: .bg = fundo; items = coadjuvantes; el = protagonista (fora do .bg, para não escurecer junto)
const bg = scene.querySelector(".bg");
tl.fromTo([bg, ...items], { scale: 1, opacity: 1 }, { scale: 0.96, opacity: 0.5, duration: 0.3, ease: "power2.out" }, t);
tl.fromTo(el, { scale: 0.8, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.4, ease: "back.out(1.6)" }, t + 0.25);

// timing & spacing: a = leve, b = pesado, mesma distância
tl.fromTo(a, { x: 0 }, { x: 600, duration: 0.3, ease: "power2.out" }, t);
tl.fromTo(b, { x: 0 }, { x: 600, duration: 0.9, ease: "power4.inOut" }, t);
// spacing em poses (12 qps): tl.fromTo(el, {x:0}, {x:600, duration:1, ease:"steps(12)"}, t);

// toss: x constante, y com gravidade (sobe freando, desce acelerando)
const T = 0.9;
tl.fromTo(el, { x: 0, rotation: 0 }, { x: 700, rotation: 360, duration: T, ease: "none" }, t);
tl.fromTo(el, { y: 0 }, { y: -400, duration: T / 2, ease: "power2.out" }, t);
tl.to(el, { y: 0, duration: T / 2, ease: "power2.in" }, t + T / 2);
